function toWebsiteBodyStr(params) {
    // params 结构: { bodyStr: {...} }
    const bodyStrValue = JSON.stringify(params.bodyStr);
    // 双重转义双引号
    const escaped = bodyStrValue.replace(/"/g, '\\"');
    // 使用 decodeURIComponent 包装（模仿网站）
    return decodeURIComponent(`bodyStr=${escaped}`);
}

function objectToQueryStringRaw(params) {
    return Object.entries(params)
        .map(([key, value]) => `${key}=${value}`)
        .join('&');
}

